contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking an amount of wei to send to C before attempting selfdestruct
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // deposit some Ether into c so there is balance to be transferred on selfdestruct
        (bool sent,) = address(c).call{value: amount}("");
        // deposit may or may not succeed depending on fallback, but we proceed either way

        // record balances before calling sudicideAnyone
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        // attempt the call and catch whether it reverts
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General rule asserted:
        // If the call did not revert then C must have been selfdestructed and transferred its entire balance to this contract:
        // - balC_after == 0
        // - balThis_after == balThis_before + balC_before
        // If the call reverted then we make no assumptions about balances.
        assert( reverted || (balC_after == 0 && balThis_after == balThis_before + balC_before) );
    }

    receive() external payable {}
}

