contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the test logic
    function run(uint sendAmount, bool expectOwner) public payable {
        require(address(this).balance >= sendAmount);

        // fund contract c if requested
        if (sendAmount > 0) {
            // send Ether to c by calling a payable no-op via selfdestruct isn't available; use plain transfer via address
            (bool ok, ) = address(c).call{value: sendAmount}("\x00");
            // the transfer might be rejected; that's allowed for setup — proceed regardless
            ok; // silence unused warning
        }

        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If expectOwner is true then this contract should be the owner and call should not revert.
        // When the call succeeds, sudicideAnyone selfdestructs C and sends its balance to msg.sender (this contract).
        // After success: C balance must be zero and this contract's balance increased by beforeC.
        if (expectOwner) {
            assert(reverted == false && address(c).balance == 0 && address(this).balance == beforeThis + beforeC);
        } else {
            // If not owner, call must revert and balances remain unchanged
            assert(reverted == true && address(c).balance == beforeC && address(this).balance == beforeThis);
        }
    }

    receive() external payable {}
}

