        } catch {
            reverted = true;
        }

        uint256 balAfter = address(c).balance;

        // General rule: either the call reverted and balance is unchanged, or it succeeded and balance is zero
        assert((reverted && balAfter == balBefore) || (!reverted && balAfter == 0));
    }

    receive() external payable { }
