import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    C c;

    function setUp() public {
        c = new C();
    }

    function _run(uint256 ) internal {
        vm.deal(address(c), VALUE_CAP);
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;
        assertTrue(!reverted || (afterC == beforeC && afterThis == beforeThis));
    }

    function testFuzz_run(uint256 ) public {
        _run();
    }

    receive() external payable {}
}

