contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test: no meaningful input needed but include one to satisfy template requirements
    function run(uint256 /*unused*/) public payable {
        // record balances before
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        // top-level state-changing call on c: sudicideAnyone takes no arguments
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterThis = address(this).balance;

        // General rule: if call reverted then balances are unchanged
        assert(!reverted || (afterC == beforeC && afterThis == beforeThis));
    }

    receive() external payable {}
}

