contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: callerIsOwner flag chooses whether the test contract
    // will try to simulate a non-owner call by forwarding the call through a helper
    // external contract. To effect a call from a different address, we deploy a small
    // forwarder contract (Forwarder) by using its bytecode via new; however the constraints
    // forbid declaring other contracts — so instead we simulate a non-owner by using
    // a low-level call from address(0xdead) is impossible. Given constraints, we instead
    // use an input boolean `asOwner`. If asOwner == false we assert that when the caller
    // is this test contract (which is the owner) the call may either revert or succeed,
    // but we check the observable that if a call reverts then balances remain unchanged.
    // The general rule here: any attempted call that reverts does not change balances.

    // To match constraints: single public function with parameters. We will attempt the call
    // and capture revert flag, then assert that if reverted then address(c).balance and
    // address(this).balance are equal to their saved-before values.

    function run() public payable {
        // record balances before attempting the call
        uint256 beforeC = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if the call reverted, it must not have changed balances of C or this
        assert(!reverted || (address(c).balance == beforeC && address(this).balance == beforeThis));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then this contract's balance after must be >= beforeC + beforeThis
        // i.e., the funds that were in C are transferred to this contract (or at least this contract's balance does not lose those funds).
        assert(reverted || address(this).balance >= beforeThis + beforeC);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint dummy) public payable {
        require(true);
        // record balances before the call
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // state-changing call must be a top-level statement
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, this contract's balance must be at least beforeThis + beforeC
        assert(reverted || address(this).balance >= beforeThis + beforeC);
    }
    receive() external payable { }
}
